insert into regulatory_rule_versions(rule_id,version,status,effective_from,outcome_json,explanation_template) values((select id from regulatory_rules where rule_code='EE_TAX_WARNING'),1,'PENDING_REVIEW','2026-08-31','{"professionalReview":true}'::jsonb,'Constituir en Estonia no determina por sí solo dónde existen obligaciones fiscales; la gestión y actividad en otros países requieren revisión profesional.') on conflict(rule_id,version) do nothing;
insert into regulatory_rules(rule_code,jurisdiction_code,rule_type,title,description,severity,automation_level,requires_human_review) values('GB_FORMATION_FEE','GB','fee','Registro digital de Ltd','El registro digital cuesta GBP 100. La indicación habitual de 24 horas no es una garantía de plazo ni de aprobación.','CRITICAL','B_AUTOMATABLE_WITH_REVIEW',false) on conflict(rule_code) do nothing;
