insert into regulatory_rules(rule_code,jurisdiction_code,rule_type,title,description,severity,automation_level,requires_human_review) values('GB_IDENTITY','GB','identity','Verificación de directores y PSC','Los nuevos directores deben verificar su identidad para constituir. Los PSC tienen requisitos y ventanas propios; no deben confundirse con los del director.','CRITICAL','B_AUTOMATABLE_WITH_REVIEW',true) on conflict(rule_code) do nothing;
insert into regulatory_rule_versions(rule_id,version,status,effective_from,outcome_json,explanation_template) values((select id from regulatory_rules where rule_code='GB_IDENTITY'),1,'PENDING_REVIEW','2025-11-18','{"newDirectorsMustVerify":true,"newPscStatementDays":14}'::jsonb,'Los nuevos directores deben verificar su identidad para constituir. Los PSC tienen requisitos y ventanas propios; no deben confundirse con los del director.') on conflict(rule_id,version) do nothing;
insert into regulatory_rules(rule_code,jurisdiction_code,rule_type,title,description,severity,automation_level,requires_human_review) values('GB_ACSP','GB','partner_action','Presentación por terceros','La plataforma no se presenta como ACSP. Para verificar identidades, el partner debe estar registrado. La guía de junio de 2026 sitúa las medidas generales de presentación por agentes no antes de noviembre de 2026. La política de este producto limita la coordinación a autopresentación o un partner verificado; no afirma que todo tercero ya deba ser ACSP.','CRITICAL','B_AUTOMATABLE_WITH_REVIEW',true) on conflict(rule_code) do nothing;
insert into regulatory_rule_versions(rule_id,version,status,effective_from,outcome_json,explanation_template) values((select id from regulatory_rules where rule_code='GB_ACSP'),1,'PENDING_REVIEW','2026-08-31','{"routes":["SELF_FILING","VERIFIED_ACSP"]}'::jsonb,'La plataforma no se presenta como ACSP. Para verificar identidades, el partner debe estar registrado. La guía de junio de 2026 sitúa las medidas generales de presentación por agentes no antes de noviembre de 2026. La política de este producto limita la coordinación a autopresentación o un partner verificado; no afirma que todo tercero ya deba ser ACSP.') on conflict(rule_id,version) do nothing;
insert into regulatory_rules(rule_code,jurisdiction_code,rule_type,title,description,severity,automation_level,requires_human_review) values('GB_CONFIRMATION','GB','annual_filing','Confirmation statement','La confirmation statement tiene una tasa digital por período de pago; la obligación de informar y el período de pago deben mantenerse separados.','CRITICAL','B_AUTOMATABLE_WITH_REVIEW',false) on conflict(rule_code) do nothing;
