insert into regulatory_rules(rule_code,jurisdiction_code,rule_type,title,description,severity,automation_level,requires_human_review) values('GB_CONFIRMATION_TIMING','GB','deadline','Plazo de confirmation statement','Se revisa la información al menos una vez cada 12 meses y se presenta dentro de los 14 días posteriores al fin del período de revisión.','CRITICAL','B_AUTOMATABLE_WITH_REVIEW',false) on conflict(rule_code) do nothing;
