insert into regulatory_rules(rule_code,jurisdiction_code,rule_type,title,description,severity,automation_level,requires_human_review) values('GB_ACCOUNTS','GB','annual_filing','Cuentas y declaración fiscal','Las primeras cuentas y las siguientes tienen plazos distintos. La declaración fiscal y el pago de Corporation Tax son obligaciones separadas sujetas al período contable confirmado.','CRITICAL','B_AUTOMATABLE_WITH_REVIEW',true) on conflict(rule_code) do nothing;
